head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00300_07.gfm";
scwin.vKisCd = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 기업코드

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_InsrncRegAsst.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    if (scwin.vKisCd == "") {
        return false;
    }
    return true;
};


/**
 * 보험가입자산 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_InsrncRegAsst);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.insrncRegAsst" + "&outputMessageId=FIS_INSRNC_REG_ASST" + "&param01=" + scwin.vKisCd;
    dts_InsrncRegAsst.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_InsrncRegAsst.Reset();
};


/**
 * 퇴직급여충당금 상세 팝업
 */
scwin.fn_InsrncRegAsstDtlSrchOpen = async function(pRow) {
    fn_GetPar = fn_GetParKey;
    await $c.frame.CreateDialogFrame("INSRNC_REG_ASST_DTL", "./ULDFIS00300_P6.gfm", "보험가입자산 검색", 100, 100, 810 + 20, 405 + 40, "window");
};


/**RETI_PAY_ALWNC_DTL
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKey = function(arrPar) {
    var nRow = dts_InsrncRegAsst.getRowPosition();
    arrPar[0] = dts_InsrncRegAsst.getCellData(nRow, "COM_CD");
    arrPar[1] = dts_InsrncRegAsst.getCellData(nRow, "BAS_YYMM");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_InsrncRegAsst.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_InsrncRegAsst, "보험가입자산", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_InsrncRegAsst_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_InsrncRegAsst);
    $c.stf.alert_error(dts_InsrncRegAsst);
};
scwin.dts_InsrncRegAsst_OnLoadCompleted = function(rowcount) {
    if (dts_InsrncRegAsst.errorMsg) {
        alert(dts_InsrncRegAsst.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_InsrncRegAsst);
};
scwin.grd_InsrncRegAsst_OnDblClick = function(row, colid) {
    if (colid == "BAS_YYMM") {
        // 보험가입자산 상세  팝업 오픈
        scwin.fn_InsrncRegAsstDtlSrchOpen(row);
    }
};
